; Huffman-compressed text group(s): $41
; Text $0820: Taloon,you'll go south if you get the Iron Safe,won't you?'<4F>I hear a big castle called Endor is in the south.You'll make a lot of money there.
; Text $0821: I see.You want to be the world's greatest arms merchant.'<4F>You need to gain experience in fighting too.'<4F>Good arms merchants should know how to use weapons properly.
; Text $0822: <4E>Tom:'The dog in the backyard is my son's.He only obeys my son.'<44>Tom:'That's why I keep him caged.'
; Text $0823: What? You want to own a shop?'<4F>You should go to Endor and buy one there.Then you can call for your family....'<4F>Nice to have a dream,eh?
; Text $0824: Hello,Traveler! Are you lost?
; Text $0825: Oh,that's too bad.Why don't you stay here tonight?
; Text $0826: Sleep well!
; Text $0827: Really? Well,have a good trip!
; Text $0828: This is an armor shop.Since the monsters began roaming around,everyone has been buying armor.'<4F>I've nothing left to sell you.
; Text $0829: We're short of armor in this Castle.'<4F>How about selling me some of yours?
; Text $082A: That's too bad.
; Text $082B: But you don't have any armor.Come back when you have some.
; Text $082C: What do you want to sell?
; Text $082D: Thanks,but we have enough weapons and other things.'<44>
; Text $082E: The <48>? I'll pay <47> gold piece<4C> for it.Is that OK?
; Text $082F: Alright,it's done.'<44>
; Text $0830: Too bad.
; Text $0831: If you sell that,you'll be in big trouble! I shouldn't buy that from you.'<44>
; Text $0832: Do you have anything else to sell?
; Text $0833: Alright,if you get more armor,come back.
; Text $0834: Endor is south of here.I went there once,before the bridge crumbled.'<4F>I met an old man there who wanted to sell his shop.
; Text $0835: Endor is a wealthy country.'<4F>Our King is determined to conquer it.
; Text $0836: This is our Prince's room.People like you are not welcome here.Get out!
; Text $0837: <4E>Reed:'I'm Reed,this country's Prince.'<44>Reed:'Assuming you're a traveling merchant,I've a favor to ask you....'<44>
; Text $0838: <4E>Reed:'Meet me at night in the weapon shop's backyard.'
; Text $0839: <4E>Reed:'Oh,here you are! It's me,Prince Reed.'<44>Reed:'I'd like you to go to Endor as soon as the bridge is repaired.'<44>Reed:'And hand this letter to the Princess of Endor.'<44>
; Text $083A: <4E>Taloon received the letter!<43><56><44>
; Text $083B: <4E>Reed:'I'm counting on you!'
; Text $083C: <4E>Reed:'Please take the letter to the Princess of Endor as soon as the bridge is repaired.I'm counting on you.'
; Text $083D: That man over there is a petty thief.'<4F>I think he's from Lakanaba.
; Text $083E: I don't see that man there anymore.
; Text $083F: Hey,Taloon! It's me! That's right,I'm the son of Grandpa Tom.'<4F>How stupid I was to get caught and sent to prison.No more thieving for me.'<4F>You're a merchant,right? Would you get me a Wing of Wyvern?
