; Huffman-compressed text group(s): $42
; Text $0840: <4E><44>'Oh,you already have one.Could I have it? I'll make it up to you when I return to my town.'
; Text $0841: Come on! Give it to me.
; Text $0842: Thanks a lot! Don't worry,I'll work hard when I return to the town.'<4F>I'll see you then,OK?'<44>Tom's son hurled the Wing of Wyvern!
; Text $0843: Grandpa Tom's son is back! How wonderful!
; Text $0844: <4E>Tom:'Oh,Taloon.My son's returned! Thank you.I'm so glad!'<44>
; Text $0845: <4E>Tom:'I'm so grateful.'<44>Tom:'It must have been fate that led you to my son.'
; Text $0846: Taloon,have you been to Endor?
; Text $0847: I bet it's a bustling place.
; Text $0848: Is the bridge still down?'<4F>I heard da Gardi went to fix it.What happened?
; Text $0849: Ah-choo! A fox tricked me out of all my armor.'<4F>Someone else was also tricked by foxes.What was his name? I think it sounded like da Gardi....
; Text $084A: <4E>Tom:'My son says he'll work hard.I'm so relieved to hear that.'<44>Tom:'My son? He's in the backyard by the dog cage.'
; Text $084B: Taloon! It's me,Tom's son! Thanks so much for everything!'<4F>Yes,I'll reward you.'<4F>What? You just want to borrow my dog,Tov? No problem.'<4F>He loves to hunt foxes.I'm sure he'll be a great help.
; Text $084C: No! Help! I hate dogs!'<4F>It's too late...my supernatural power is....
; Text $084D: Yelp,Yelp! I'm sorry.Please let me go.I won't play tricks anymore.
; Text $084E: Don't be so cruel! Forgive me!
; Text $084F: Thanks! Here,let me give you this armor in appreciation.'<44>
; Text $0850: <4E><44>'Yelp,Yelp! Bye now!'
; Text $0851: Are you a merchant who has done business with us before?
; Text $0852: Then you came to sell the King something.'<4F>We don't deal with new merchants unless they've got something extraordinary.You should forget it.
; Text $0853: I hear magnificent treasures are in the cave,but many terrible monsters live there.'<4F>Why don't you hire me as your guardsman for 400 gold pieces for 5 days?
; Text $0854: But I hate dogs! Return him and come back.
; Text $0855: But you don't have enough money.Come back when you do.
; Text $0856: Oh,you do? Alright! I'll go anywhere with you.'<44>Strom joined the Party!<43><55><40>
; Text $0857: Oh well.If you change your mind,come see me.
; Text $0858: Are you a merchant too? Did you come here for the Silver Statue?
; Text $0859: Me too.I'm certain it will fetch a great price.
; Text $085A: Oops! Forget what I said then.Ha,Ha,Ha.
; Text $085B: Mumble...Mumble....If the Silver Statue is in the cave,he should just go get it....'<4F>My husband is such a coward.
; Text $085C: I've trained myself to cast some spells.'<4F>How about hiring me for 600 gold pieces for 5 days?
; Text $085D: Oh,you don't seem to have enough money.When you do,please come back.
; Text $085E: Oh,you do? Let's go then.'<44>Laurent joined the Party!<43><55><40>
; Text $085F: Well,if you change your mind,please come see me.
Bank04_TextGroup_42:
