; Huffman-compressed text group(s): $43
; Text $0860: I heard that people disappeared from Santeem in the west.What happened to them?
; Text $0861: Is there anyone who has the King's permission to do business and wants to buy my shop?
; Text $0862: How about buying my shop for 35000 gold pieces?
; Text $0863: That's too bad.
; Text $0864: But you don't have enough money.Don't tease me.
; Text $0865: You do? Alright,from now on,you're the owner of this shop.
; Text $0866: <4E>Neta:'Are you tired already? It's still early,but you want to sleep?'
; Text $0867: <4E>Neta:'I'll stay at the shop and you bring in the merchandise,OK?'<44>Neta:'When you speak to me over this counter,I'll take the goods you bring and put them up for sale.'
; Text $0868: Our family has been wealthy for a long time,and my husband is a collector of valuable things.'<4F>Still,we can't use up all our money.He,He,He.
; Text $0869: I love to collect antiques.'<4F>I hear the Silver Statue exists somewhere.
; Text $086A: <4E><44>'I want it.I don't care what it costs.'
; Text $086B: Wait a minute! Isn't that the Silver Statue in your hand?!'<4F>I'll pay 20000...no,25000 gold pieces for it! Will you sell it to me?
; Text $086C: Thank you so much!
; Text $086D: No? If you change your mind,come back anytime and sell it to me.
; Text $086E: The Silver Statue is beautiful.'<4F>...by the way,I hear there once was a sword called the Zenithian Sword.
; Text $086F: Now the tournament is over,this place will be closed for a while.
; Text $0870: You aren't allowed to enter.Leave!
; Text $0871: I see you're an arms merchant.I hear there are many powerful weapons these days.'<4F>The soldiers in this Castle are still using copper swords.It's a shame....
; Text $0872: The King has so many responsibilities.He doesn't have time to worry about our weapons.
; Text $0873: Are you here to deliver weapons and armor to the King?
; Text $0874: Then I'll take your Broad Sword and Half Plate Armor.
; Text $0875: <50> Broad Sword<4C>!
; Text $0876: <47> suit<4C> of Half Plate Armor!
; Text $0877: I've made a record of the delivery.'<44>
; Text $0878: What? You haven't brought anything yet?'<44>
; Text $0879: The rest of the order is...'<44>
; Text $087A: Keep bringing them.
; Text $087B: Great! You filled the order.You'll be paid as promised.'<44>Taloon received 60000 gold pieces!<44>
; Text $087C: I appreciate your effort.I wish you good luck in your business.
; Text $087D: When you fill the order,you'll be paid 60000 gold pieces.'<4F>You can buy them in other towns if you want.Do your best.
; Text $087E: Ho,Ho,Ho.You made a tremendous amount of money.'<4F>Use it wisely.
; Text $087F: What? Do you want to stop for today?
