; Huffman-compressed text group(s): $44
; Text $0880: Thanks.Let me add up your earnings for today.'<4F>Here are your wages.'<44>Taloon received <47> gold piece<4C>!<44>
; Text $0881: See you tomorrow.
; Text $0882: Then go back to work.'<4F>See me when you're done for the day,OK?
; Text $0883: <4E>Mia:'You came from Lakanaba? That must mean the bridge was repaired!'
; Text $0884: <4E>Mia:'My father probably has a good idea.I always trust him.'
; Text $0885: <4E>Mia:'I can marry Reed! It's like a dream!'<44>Mia:'Taloon is your name,is it not? Thank you so much.I'm so grateful.'
; Text $0886: I commend you for traveling so far to see me.'<4F>Hmm...you want my permission to own a shop here in Endor?
; Text $0887: I heard your request.I'll think about it.You can leave now.
; Text $0888: Oh,that's good.Too many people have been making the same request.
; Text $0889: Give this letter to the King of Bonmalmo.'<4F>It's not the time for us humans to be fighting each other.'<4F>Help prevent the war,and I'll give you permission to own a shop.
; Text $088A: Taloon! Welcome back!'<4F>I received the message from the King of Bonmalmo.'<4F>Thanks for your help.As promised,I give you permission to own a shop.
; Text $088B: Taloon,keep up the good work,not only for yourself but for the world and all its people.'<4F>Remember to report to me when you open a shop.
; Text $088C: Taloon! I hear you own a shop now.'<4F>How about taking a big order from me?'<4F>I want you to collect weapons and armor for my soldiers and deliver them to the people downstairs.'<4F>My order is 7 Broad Swords and 7 suits of Half Plate Armor!
; Text $088D: Thanks for providing the weapons and armor to my soldiers.'<4F>By the way,have you heard of the Zenithian Sword?'<4F>I hear it's the most powerful sword in the world.It can even break rocks,they say.'<4F>I wish I could get it....
; Text $088E: My son,Reed,will be the next King of Endor.Ha,Ha,Ha!
; Text $088F: <4E>Reed:'I heard  the story from my father.If you happen to go to Endor,please tell Mia that...'<44>Reed:'I'm looking forward to our marriage!'
; Text $0890: The monsters are getting stronger these days.Many castles are buying many weapons and armor.'<44>
; Text $0891: I envy you for being an arms merchant.You must be making tons of money.
; Text $0892: I began digging a cave to go to an eastern port town.'<4F>I dreamt of owning a ship and retrieving all the treasures of the world.'<4F>But I ran out of money and I'm getting old too.'<4F>If there were 60000 more gold pieces,the excavation could be started again.Would you like to carry on my dream?
; Text $0893: Too bad....
; Text $0894: Are you sure? Then you must own a shop first.Everything starts there.
; Text $0895: You do? Then I'll wait for you to bring me 60000 gold pieces.
; Text $0896: You do? Yes,I've received 60000 gold pieces.'<44>
; Text $0897: I'll use this money to hire people and restart the excavation.Be assured it'll be finished.
; Text $0898: Taloon.Look,I started the excavation again.'<4F>When it's done,I'll send a message to your house.It will be soon.
; Text $0899: Hi,Taloon! You came here to return my dog?
; Text $089A: Good boy,Tov.Now,go back to your cage.'<44>
; Text $089B: I wish you the best of luck,Taloon.
; Text $089C: Well,come back whenever you feel like returning my dog.I'll be here.
; Text $089D: Do you want to work here? Sorry,I don't need any new workers.
; Text $089E: You now own a shop in Endor? That's great!
; Text $089F: I heard you bought a shop in Endor.Congratulations! You're the most successful person from our town.
