; Huffman-compressed text group(s): $45
; Text $08A0: <4E>Neta:'Hello,darling.I just received a message that the cave was completed.'<44>Neta:'I didn't understand what it meant....'<44>Neta:'Are you leaving on a journey again?'
; Text $08A1: <4E>Neta:'Hello,darling.What? A message? No,I haven't received any.'<44>Neta:'Anyway,aren't you a little tired of working?'<44>Neta:'I hear the Casino reopened.Why don't you go there and relax?'
; Text $08A2: <4E>Neta:'Alright,I won't say anything.'
; Text $08A3: <4E><44>Neta:'You're always chasing dreams....'<44>Neta:'But that's what I love about you.'<44>Neta:'Why don't you go? I'll be waiting for your return.'
; Text $08A4: <4E>Neta:'You don't have to lie to me....'<4F>Neta:'I've heard about the Zenithian Sword too.You want to search for it,right?
; Text $08A5: Taloon! The cave is finished!'<4F>Carry on my dream and collect as many treasures as possible.
; Text $08A6: I'm traveling the world in search of a legendary sword.'<4F>If you go through the cave and reach an eastern country,you may find out something about it.
; Text $08A7: Many people go through this cave hoping to fulfill their dreams.'<4F>Taloon,I wish you good luck on your journey.
; Text $08A8: The stage is downstairs.
; Text $08A9: <4E><44>'Mara! I thought you left town.You're back!'
; Text $08AA: Mara!'<4F>I'm so excited to talk with you.
; Text $08AB: Oh,Mara! You are...no!
; Text $08AC: Mara,it's you! I heard you quit,but you're back.I'm glad!
; Text $08AD: I want to be on stage too....
; Text $08AE: This is the Village of Kievs.
; Text $08AF: <4E><44>'You must be Edgar's daughters! You're back!'
; Text $08B0: You're Edgar's daughters!'<4F>I can't accept money from you.You're from this village.'<4F>There's no charge.Would you like to stay?
; Text $08B1: Rest well.
; Text $08B2: Good morning.Have a safe journey.
; Text $08B3: I see.Be careful on your journey.
; Text $08B4: It's a shame a man like Edgar was betrayed by his pupil.'<4F>Say,didn't Edgar have another pupil? Orin...that's his name,I think.'<4F>He was terribly injured too.Where is he now?
; Text $08B5: Isn't that you,Orin? You're alive.Glad to see you again!
; Text $08B6: How long has it been since Edgar died?'<4F>The stray puppy Nara took in back then has grown up.
; Text $08B7: Hey,it's you,Nara! Isn't it nice to be back in your hometown?
; Text $08B8: Oh,Mara!'<4F>I told you not to seek revenge....
; Text $08B9: I despise Balzack! He became Edgar's pupil to steal his invention.
; Text $08BA: <4E><44>'By the way,this is a secret....'<4F>Orin,Edgar's other pupil,is hiding in the cave west of this village.'<4F>Orin may know Balzack's whereabouts....
; Text $08BB: Rumor is Edgar failed to make gold.'<4F>But he made an extraordinary discovery.Ah...the Secret of Evolution...that's it.
; Text $08BC: Don't hurt me! I'm not a bad Slime!'<44>
; Text $08BD: Do you know? Orin used to break open locked doors.
; Text $08BE: Huh? Mara and Nara! It's me,Orin!'<4F>You're after revenge? I've been recovering,dreaming of revenge too.'<4F>Balzack allied himself with the evil ones and gained great magic powers.'<4F>But the Sphere of Silence should help you overcome his magic powers!'<44>
; Text $08BF: Oh,you already have it!'<44>
