; Huffman-compressed text group(s): $46
; Text $08C0: I'll accompany you.Let's go!'<44>Orin joined the Party!<43><55><40>
; Text $08C1: Where's the King's chamber? I don't know.'<4F>They say the new King is always in the secret chamber.
; Text $08C2: He,He,He.I won't let you go.He,He,He.
; Text $08C3: No! I'll be caught! Huff,Huff.
; Text $08C4: Strange...I hear voices below.
; Text $08C5: Good food,dance,and song....Isn't this place like paradise?
; Text $08C6: Indulging in ultimate luxury is allowed here.'<4F>I'm so H<4B>A<4B>P<4B>P<4B>Y!
; Text $08C7: Wa,Ha,Ha! I'll catch you!
; Text $08C8: Get out of my way! I'll be caught! Eee,Eee...
; Text $08C9: I'm this Castle's scholar of magic.'<4F>What type of magic? I wouldn't tell you.Ha,Ha,Ha.
; Text $08CA: Mumble...Mumble...Bring more girls!'<44>
; Text $08CB: In order to complete the Secret of Evolution,the essence of girls' youth is needed....
; Text $08CC: This Castle's Counsel is a nervous type.'<4F>Some time ago,the man who made a big sound by the Counsel's room was thrown into jail in the port town.'<4F>Where's the port town? It's on the shore north of this Castle.
; Text $08CD: This is the House of Prophecy.'<44>
; Text $08CE: The man you seek revenge upon is protected by a tremendous evil force.'<4F>Worry not.'<4F>I see you are protected by radiant lights....'<4F>They are small and frail now,but more lights will join them and they'll fuse into one powerful force.'<4F>Be patient.When you are sunk in the depths of despair...'<4F>then shall your true journey begin.
; Text $08CF: This is Haville,a port town where ships bound for Endor depart.
; Text $08D0: The regulation has become more strict since the new King took over Keeleon.'<4F>It's very difficult to get boarding passes these days.
; Text $08D1: Ships don't leave at night.Come back during the day.
; Text $08D2: You can't get boarding passes anymore.Only those who obtained them in the former King's time have them.'<4F>The next ship may be the last one to leave this town.
; Text $08D3: I fell in love with a girl! I'll marry her.'<4F>Who's she? Her name is Joy! Hee ha!
; Text $08D4: I'm happy! Yes,HAPPY!
; Text $08D5: Really? You're on a journey of revenge? The object of your revenge is named Balzack?!'<4F>The name of Keeleon's new King is also...I think...Balzack....No,must be someone else.
; Text $08D6: This is Jail.Those who disobey the King of Keeleon are put here.
; Text $08D7: I didn't disobey the King.'<4F>I just accidentally ignited gunpowder near the room of the Castle's Counsel....'<4F>The gunpowder? I got it at Aktemto Mine when I was working there.
; Text $08D8: I hear the Sphere of Silence can contain the magic spells of your opponent.
; Text $08D9: This is Aktemto,a mining town.It's not safe to live here anymore.
; Text $08DA: The Castle prohibited gunpowder manufacturing.'<4F>If you need gunpowder,take some of what's left in the mine.Cough...Cough...
; Text $08DB: You've come for gunpowder? It's in the jar.'<4F>But it's damp and may not work except to make a loud noise.
; Text $08DC: Do you have a Boarding Pass? If not,I can't let you aboard.
; Text $08DD: You brought a Boarding Pass.Hurry! The ship will sail soon.
; Text $08DE: The cabins are downstairs.
; Text $08DF: I'm the captain.We'll sail soon.Wait in your cabin.
