; Huffman-compressed text group(s): $47
; Text $08E0: Once the ship leaves,you won't be able to come back to this country.'<4F>Do you have anything you should take care of before leaving? Can we sail now?
; Text $08E1: Well then,let's sail.Raise the Anchor!
; Text $08E2: In that case,go finish what you have to do.We'll wait for you.
; Text $08E3: I won't tell my brother,Pipin,what happened to our father...'<4F>until he's old enough to bear agony and despair....
; Text $08E4: I'm the Counsel.'<4F>This is my room.Leave now or I'll have you put in jail.
; Text $08E5: What are you doing here? Get away!
; Text $08E6: Wh...Who are you? This is King Balzack's room.
; Text $08E7: I remember.You're Edgar's daughters.'<4F>You came here to avenge your father.Yes,I'm Balzack.'<4F>Edgar tried to destroy the Secret of Evolution which he accidentally discovered.'<4F>What a fool.With it,he could have ruled the world....'<4F>Look at me! At my strength! At my superior body!
; Text $08E8: Cough...Cough...I'm nearing my end.I wanted to escape from this country,but I ran out of strength.'<4F>You're still young.I'll give you my Boarding Pass.It's in the chest in the back.'<4F>Escape for me and live....
; Text $08E9: <4E>Orin:'I...I don't think I can accompany you anymore.'<44>Orin:'I know you regret what happened,but leave this country now and build up your strength.'<44>Orin:'I'll be wishing you...a safe journey...<4B>Gasp!'<43><53><40>
; Text $08EA: Deliver the lunch,then you can have yours,OK?
; Text $08EB: Thank you! Do you want your lunch?
; Text $08EC: OK,sit there.I'll make it.
; Text $08ED: OK,why don't you go and play outside?
; Text $08EE: This is the entrance to the village.I guard this entrance so no strangers can enter.'<4F><49>,do you want to go outside?
; Text $08EF: You're not ready to go out yet.You must be much stronger.
; Text $08F0: That's good.You must be much stronger to go out.
; Text $08F1: You brought me lunch,<49>?'<44>
; Text $08F2: What? You ate my lunch? Oh,goodness!'<44>
; Text $08F3: <49>,you're already 17 years old,entering adulthood.'<44>
; Text $08F4: Listen,<49>,you must always be righteous and strong,whatever happens.
; Text $08F5: It's you again! Stay here tonight if you want to!
; Text $08F6: Are you going to sleep forever? Get out of here!
; Text $08F7: What? You think I'm rude but have a soft heart?'<4F>Oh,c'mon! Get lost!
; Text $08F8: I hear a famous fortuneteller is staying in Endor.'<4F>I want to consult her.
; Text $08F9: How do you like our dance? We're imitating the moves of the famous dancer in Endor.'<4F>She told me she was searching for the Hero with her little sister.
; Text $08FA: We're traveling the world to defeat the monsters.'<4F>Do you want to join our party?
; Text $08FB: Oh,sorry! Our party is full.'<4F>You should find your own allies.
; Text $08FC: Alright.See you then.
; Text $08FD: Walking at night feels so good.
; Text $08FE: Whenever I see the moon's reflection on the water,I remember this.'<4F>Long ago,a woodsman's family lived in the northern woods.'<4F>The son met a beautiful girl in the woods and fell in love with her.'<4F>One day he was struck by lightning and died.'<4F>His father is still a woodsman and lives alone in the mountains.
; Text $08FF: You're not a member of that four-member party that was just here?'<4F>Many people,claiming they can defeat the monsters,come to see the King.
