; Text $0900: I hear the Princess of Endor and the Prince of Bonmalmo are getting married.I'm envious.
; Text $0901: Welcome! So you are traveling to save the world too.'<4F>Your name is <49>? A good name!'<4F>I'll tell you what you must do.'<4F>Prevent the resurrection of the Ruler of Evil at any cost.'<44>
; Text $0902: <49>,I wish you luck!
; Text $0903: It must be hard for a girl like you,but I wish you luck,<49>!
; Text $0904: This cave connects Endor and Branca.
; Text $0905: What a great man Taloon is to have dug a cave like this.
; Text $0906: If you ever meet Taloon,tell him this old man is worried about him.
; Text $0907: Taloon! You're alive! Good to see you again.
; Text $0908: My husband,Taloon,is on a journey to search for a legendary sword.'<4F>It's rumored that the monsters are chasing him.'<4F>I hope he's traveling with someone strong.
; Text $0909: Oh,dear! It's you! Welcome home!'<4F>Don't worry about me.I'll be here when you return after fulfilling your dream.
; Text $090A: I saw a girl walking down to the Casino.What a beauty!
; Text $090B: I love to dine with a beautiful girl.
; Text $090C: They were right! Her predictions come true.'<4F>Why don't you let her tell your fortune.
; Text $090D: Thanks to Nara,I now know how I should live my life.'<4F>Everyone has their own destiny.
; Text $090E: <4E>Nara:'Would you like to hear your fortune for just 10 gold pieces?'
; Text $090F: <4E>Nara:'A fortune is like moonlight in the darkness.If you change your mind,come see me.'
; Text $0910: <4E>Nara:'Alright,I'll tell your fortune.'<44>Nara:'I see seven lights around you.'<44>Nara:'They are small now,but they will soon grow...what?'<44>Nara:'You are the Hero!'<44>Nara:'I've been searching for you,the one with the untapped power to defeat the evil ones.'<44>Nara joined the Party!<43><55><44>Nara:'Let's go.My sister,Mara,should be at the Casino.'
; Text $0911: It's wonderful that the Princess of Endor and the Prince of Bonmalmo got married.'<4F>At least,we must avoid conflict among ourselves.
; Text $0912: The wedding was magnificent!
; Text $0913: <4E>Mara:'Be quiet! I can't concentrate!'<44>Mara:'I'll recover my losses and surprise my little sister,Nara.'
; Text $0914: <4E>Nara:'I knew you'd be here!'<43>Mara:'Uh-oh!'<44>Nara:'You spend all the money I earn on gambling! We're broke!'<44>Mara:'I'm sorry....'<44>
; Text $0915: <4E>Mara:'Huh? Who is this?'<44>
; Text $0916: <4E>Nara:'This is the Hero we've been searching for.'<44>Mara:'How nice! You can take care of us from now on,right?'<44>Mara joined the Party!<43><55><44>Mara:'Let's go!'
; Text $0917: <4E>Mara:'Whose ghost is this?'<44>
; Text $0918: You shouldn't be here.Jump off from there and get out!
; Text $0919: Because my father is away,we can't get our stock replenished.That's why my mother started a vault business.
; Text $091A: Did you know that Necrosaro who was in the tournament was not human?'<4F>It's just a rumor,but I thought he was too strong to be a human.
; Text $091B: <4E><44>'At least this marriage was a good thing.'
; Text $091C: There's a waiting room in the back for the bride and bridegroom.
; Text $091D: You came to see the wedding? Go up the stairs on the right.
; Text $091E: There's a rumor a man named Taloon crossed the eastern desert with a caravan.
; Text $091F: Huh? Haven't I seen you before?
