; Huffman-compressed text group(s): $49
; Text $0920: You want to go east?'<4F>I'm afraid you won't be able to cross the desert without a wagon.
; Text $0921: <4E><44>'Really? The wedding is going on? I wanted to attend too.'
; Text $0922: You're traveling to save the world? You want the wagon? No.I don't trust you.'<4F>Leave me alone!
; Text $0923: Never come back!
; Text $0924: You just don't get it,do you?'<4F>I used to travel like you.'<4F>One day I heard of a cave where the world's most valuable treasure was hidden.'<4F>I went to the cave with my best friend.'<4F>I trusted him,but he betrayed me and...Darn....'<4F>I just can't trust anyone anymore! Go away!
; Text $0925: Have you talked to the wagon's owner? I'm his father.'<4F>He once went to an eastern cave with his friend.'<4F>Only my son returned,unconscious and injured,on his horse,Primrose....'<4F>He changed after that.He doesn't trust anyone.'<4F>What happened in that cave,I wonder....
; Text $0926: It's too bad.A wagon is essential for crossing the desert,but the owner is....
; Text $0927: You again? Ha? Wh...What's that gem?'<4F>Why? Looking at it seems to purify my mind....The Symbol of Faith....'<4F>I got it! The most valuable treasure has been none other than trusting each other!'<4F>I've been wrong.'<4F>Let me join your Party.Of course we can take the wagon.'<44>Hector joined the Party!<43><55><44>Hector:'Shall we go now?'
; Text $0928: My son seems to have straightened out.Thanks.Look after him,will you?
; Text $0929: South of this desert,lies Konenber,a port town.
; Text $092A: Hello there! Your first time in this town? Shall I show you around?
; Text $092B: Alright.Follow me!
; Text $092C: You're sure? By the way,you'd better avoid this inn.It's not good.
; Text $092D: I'm going to bathe in the spa pool.
; Text $092E: Do you want to come with me to bathe? You're not afraid of the water,are you? Just jump in!'<4F>Look at those muscles! Did you inherit them from your father or your mother?
; Text $092F: Sorry,we open at night.
; Text $0930: A ship is being built at the wharf.It's the big building to the left.
; Text $0931: Darn,my ship is gone! The lighthouse in the east is responsible.'<4F>Since the monsters took over the lighthouse,it's been emanating an evil light that sinks ships.
; Text $0932: I don't feel like opening my shop these days.'<4F>A port town without ships! What a joke!
; Text $0933: You're unfortunate.Until recently,ships used to sail out of here.
; Text $0934: How would you like to marry me?
; Text $0935: You're so naive.I was only kidding!
; Text $0936: Wh...Who are you? I...I was only telling her an old proverb.
; Text $0937: !!'
; Text $0938: I'm sorry.I was tempted but...'<4F>I haven't stolen anything yet.Forgive me.
; Text $0939: Please,show me mercy.
; Text $093A: Thank you! I'll tell you something in gratitude.'<44>
; Text $093B: You can exchange Small Medals for items.
; Text $093C: The eastern lighthouse was invaded by monsters recently.'<4F>Since then,it's been shining evil lights on the sea.
; Text $093D: Why isn't Taloon back? The ship's almost finished.'<4F>I hope the monsters at the lighthouse haven't got him.
; Text $093E: I'm worried.'<4F>We're building this ship for Taloon,but he's so rash.'<4F>He went to the lighthouse to destroy the monsters who are making sailing impossible.
; Text $093F: <4E>Taloon:'It's you! I was looking at the sea.'<44>Taloon:'Yes,the ship will be completed soon.I'll wait for you to return with good news.'
