; Huffman-compressed text group(s): $4A
; Text $0940: You'll do that for Taloon?...defeat the monsters at the lighthouse? Be careful,OK?
; Text $0941: <4E><44>'It seems he couldn't do it,and he's back in town.'
; Text $0942: <4E>Taloon:'Thank you! The evil lights are gone,and the sea is so calm now.'<44>Taloon:'And the ship is finally finished!'<44>Taloon:'I've one favor to ask of you.Monsters are after me.'<44>Taloon:'I'd feel safer being with strong people like you.'<44>Taloon:'Let me join you.Let's travel together all over the world!'
; Text $0943: <4E>Taloon:'Why not? Come on.'
; Text $0944: <4E>Taloon:'I appreciate it! Let's leave right away.'<44>Taloon joined the Party!<43><55><44>Taloon:'Starboard the Helm!'
; Text $0945: Incredible! You defeated the monsters at the lighthouse?
; Text $0946: We can't always judge people by their looks,but you're somebody special,aren't you?
; Text $0947: As I thought.I could tell!
; Text $0948: Don't be so modest? I can tell.
; Text $0949: My ship remains sunken.Weep...
; Text $094A: The eastern lighthouse has returned to normal.'<4F>Thanks to you,ships can now leave.
; Text $094B: You defeated the monsters at the lighthouse? Th...Thank you!
; Text $094C: Many hardships may be ahead of you.'<4F>Don't ever give up hope....
; Text $094D: I remember fondly my days building Taloon's ship.
; Text $094E: Kiii...Kiii...Where's Taloon?'<4F>I've been waiting to ambush him.I heard he was coming to this lighthouse....'<4F>He must have gotten scared and headed back to town!'<4F>I'll go there and get him! Kiii...Kiii...'<44>
; Text $094F: <4E>No response.<43>Seems unconscious.
; Text $0950: The chancellor staying at the big inn fell ill.'<4F>The legendary herbal medicine,Padequia,should cure him....
; Text $0951: <4E>Howden:'What? Are you asking if I'm the old man who's an expert on the seas?'
; Text $0952: <4E>Howden:'You idiot! I'm not only an expert on the seas but on the whole world also.'<44>Howden:'Come back again!'
; Text $0953: <4E>Howden:'I'm impressed...I'm not only an expert on the seas but on the whole world also.'<44>Howden:'You seem promising.'<44>Howden:'What do you say? Would you like to take my quiz?'
; Text $0954: <4E>Howden:'I see.That's too bad.'
; Text $0955: <4E>Howden:'Here's the quiz.What's most important in business?'<44><49>:'.........?'<44>Howden:'Mmm....Well Done! Don't say anything...yes,Silence Is Golden!'<44><49>:'???'<44>Howden:'I'll give you the Treasure Map.'<44>Howden:'I discovered it when I was young but haven't been able to uncover its secret....'<44>Howden:'Please accept it!'<44>
; Text $0956: <4E><49> received the Treasure Map!<43><56><44>
; Text $0957: <4E>Howden:'Perhaps you can reveal the secret of this Treasure Map.Good luck!'
; Text $0958: <4E>Howden:'I really meant it,but you can't carry any more things! Come back again.'
; Text $0959: There's a small country called Soretta in the very eastern reaches of this land.'<4F>When I told this to the Princess at the inn,she darted out.
; Text $095A: <4E>Brey:'One of my traveling companions is gravely ill.'<44>Brey:'Our mistress,Princess Alena,went to get medicine alone.I'm very worried....'<44>Brey:'You look kind.'<44>Brey:'Will you find Princess Alena and help her?'
; Text $095B: <4E>Brey:'That's very thoughtful of you.I'll accompany you!'<44>Brey joined the Party!<43><55><44>Brey:'I must ask the people of this inn to take care of Cristo.'<44>Brey:'I'll meet you outside later.'
; Text $095C: <4E>Brey:'As I feared....'
; Text $095D: This is Soretta,the country known for growing Padequia,the cure-all herb.
; Text $095E: <4E><44>'Well,at least it used to be....
; Text $095F: I'm a farmer,just a ploughman,Hey! Been plowing fields for thirty years,Hey! Ho!'<44>
